  name: 'fake-chrome',
  startSession: async () => ({ targetRef: 'about:blank', viewport: { width: 1440, height: 900 } }),
  navigate: async (url) => ({ url, loaded: true }),
  click: async (point) => ({ ...point, clicked: true }),
  clickSelector: async (selector) => ({ selector, clicked: true }),
  waitForSelector: async (selector) => ({ selector, visible: true }),
  waitForUrl: async (url) => ({ url, matched: true }),
  dismissOverlays: async () => ({ dismissed: true }),
  inspectMedia: async () => ({ url: 'https://example.com', title: 'Fixture', mediaCount: 0, playingCount: 0, pausedCount: 0, endedCount: 0, currentTimeMax: 0, durationMax: null, readyCount: 0, blockedReasons: [], goalSatisfied: false }),
  verifyMediaPlayback: async () => ({ goalSatisfied: false, reason: 'not media', state: { url: 'https://example.com', title: 'Fixture', mediaCount: 0, playingCount: 0, pausedCount: 0, endedCount: 0, currentTimeMax: 0, durationMax: null, readyCount: 0, blockedReasons: [], goalSatisfied: false } }),
  typeText: async (text) => ({ characters: text.length, typed: true }),
  observe: async () => ({ url: 'https://example.com', title: 'Fixture', text: 'condition ready', observed: true }),
  scroll: async (direction) => ({ direction, scrolled: true }),
  pressKey: async (key) => ({ key, pressed: true }),
  captureScreenshot: async () => ({ bytes: new Uint8Array([137, 80, 78, 71]), mimeType: 'image/png', width: 2, height: 2, metadata: { url: 'https://example.com', cursorVisible: true } }),
  stop: async () => undefined
};
const runtime = new AutomationRuntime({
  repository: repo,
  artifactRoot: join(dir, 'artifacts'),
  browser,
  autonomy: 'unattended',
  agenticConfig: { maxSteps: 4, maxRetries: 0, vision: true },
  agentic: decider
});
try {
  const started = await runtime.startRun({
    goal: 'open example.com and inspect the page until condition ready',
    mode: 'browser',
    ownerUserId: 'local-user',
    projectId: 'ultron'
  });
  const startedAt = Date.now();
  while (Date.now() - startedAt < 4000) {
    const snapshot = await runtime.getRun(started.session.id);
    if (snapshot.session.status === 'completed') {
      break;
    }
    await new Promise((resolve) => setTimeout(resolve, 50));
  }
  const snapshot = await runtime.getRun(started.session.id);
  assert.equal(snapshot.session.status, 'completed');
  assert.equal(snapshot.session.metadata.goalSatisfied, true);
  assert.equal(captured.length, 3);
  assert.deepEqual(captured.map((entry) => entry.previousResponseId ?? null), [null, null, null]);
  assert.ok(captured[1].historyLength >= 1, 'later turns should still carry recent action history');
  assert.ok(captured.every((entry) => entry.pageText.includes('condition ready')), 'each turn should include fresh page text');
  assert.ok(captured.every((entry) => typeof entry.screenshotBase64 === 'string' && entry.screenshotBase64.length > 0), 'each turn should include screenshot context when vision is enabled');
} finally {
  await repo.close();
  rmSync(dir, { recursive: true, force: true });
}
