143	func buildBrainHistoryIndex(outputDir string, now time.Time) (historyIndex, *historySourceManifest, error) {
144		sessionsRoot := filepath.Join(outputDir, exportSessionsDirectory)
145		index := historyIndex{GeneratedAt: now}
146		if _, err := os.Stat(sessionsRoot); err != nil {
147			if os.IsNotExist(err) {
148				return index, nil, errors.New("session history missing; run `entire brain export` first")
149			}
150			return index, nil, err
151		}
152		files, err := collectHistorySessionFiles(sessionsRoot, &index.Warnings)
153		if err != nil {
154			return index, nil, err
155		}
156		seenDecisions := map[string]struct{}{}
157		for _, file := range files {
158			records, scanErr := scanHistoryFile(outputDir, file.Path)
159			if scanErr != nil {
160				index.Warnings = append(index.Warnings, scanErr.Error())
161				continue
162			}
163			for _, record := range records {
164				if record.Kind == "decision" {
165					dedupeKey := normalizeHistorySearchText(record.Summary)
166					if _, ok := seenDecisions[dedupeKey]; ok {
167						continue
168					}
169					seenDecisions[dedupeKey] = struct{}{}
170				}
171				index.Records = append(index.Records, record)
172			}
173		}
174		sort.Slice(index.Records, func(i, j int) bool {
175			if index.Records[i].Kind != index.Records[j].Kind {
176				return index.Records[i].Kind < index.Records[j].Kind
177			}
178			if index.Records[i].Path != index.Records[j].Path {
179				return index.Records[i].Path < index.Records[j].Path
180			}
181			return index.Records[i].Line < index.Records[j].Line
182		})
183		source := &historySourceManifest{
184			GeneratedAt:         now,
185			IndexPath:           historyIndexPath,
186			SessionsFingerprint: brainSessionsFingerprint(outputDir),
187			Records:             len(index.Records),
188			Warnings:            append([]string(nil), index.Warnings...),
189		}
190		for _, record := range index.Records {
191			switch record.Kind {
192			case "decision":
193				source.Decisions++
194			case "learning":
195				source.Learnings++
196			case "validation":
197				source.Validations++
198			case "tool_call":
199				source.ToolCalls++
200			case "code_fact":
201				source.CodeFacts++
202			}
203		}
204		return index, source, nil
205	}
