254	func collectHistorySessionFiles(sessionsRoot string, warnings *[]string) ([]historySessionFile, error) {
255		var files []historySessionFile
256		err := filepath.WalkDir(sessionsRoot, func(path string, d fs.DirEntry, err error) error {
257			if err != nil {
258				*warnings = append(*warnings, err.Error())
259				return nil
260			}
261			if d.IsDir() {
262				return nil
263			}
264			ext := filepath.Ext(path)
265			if ext != ".jsonl" && ext != ".json" && ext != ".md" && ext != ".txt" {
266				return nil
267			}
268			info, statErr := d.Info()
269			if statErr != nil {
270				*warnings = append(*warnings, statErr.Error())
271				return nil
272			}
273			files = append(files, historySessionFile{
274				Path:     path,
275				SortTime: historySessionSortTime(path, info.ModTime()),
276				Size:     info.Size(),
277			})
278			return nil
279		})
280		if err != nil {
281			return nil, err
282		}
283		sort.Slice(files, func(i, j int) bool {
284			if !files[i].SortTime.Equal(files[j].SortTime) {
285				return files[i].SortTime.After(files[j].SortTime)
286			}
287			return files[i].Path < files[j].Path
288		})
289		return files, nil
290	}
