292	func historySessionSortTime(path string, fallback time.Time) time.Time {
293		base := filepath.Base(path)
294		if len(base) >= len("20060102T150405Z") {
295			if parsed, err := time.Parse("20060102T150405Z", base[:len("20060102T150405Z")]); err == nil {
296				return parsed
297			}
298		}
299		return fallback
300	}
