302	func scanHistoryFile(outputDir, path string) ([]historyRecord, error) {
303		f, err := os.Open(path)
304		if err != nil {
305			return nil, err
306		}
307		defer f.Close()
308		rel, _ := filepath.Rel(outputDir, path)
309		rel = filepath.ToSlash(rel)
310		scanner := bufio.NewScanner(f)
311		scanner.Buffer(make([]byte, 0, 64*1024), historyMaxLineBytes)
312		var records []historyRecord
313		lineNumber := 0
314		allowRawText := filepath.Ext(path) == ".md" || filepath.Ext(path) == ".txt"
315		for scanner.Scan() {
316			lineNumber++
317			text := strings.TrimSpace(scanner.Text())
318			if text == "" {
319				continue
320			}
321			if !historyLineMayContainIndexedContent(text) {
322				continue
323			}
324			for _, fragment := range extractHistoryFragments(text, allowRawText) {
325				fragment.Text = strings.TrimSpace(fragment.Text)
326				if fragment.Text == "" {
327					continue
328				}
329				for _, kind := range classifyHistoryFragment(fragment) {
330					records = append(records, historyRecord{
331						ID:      historyRecordID(rel, lineNumber, kind, fragment.Text),
332						Kind:    kind,
333						Path:    rel,
334						Line:    lineNumber,
335						Summary: truncateString(cleanHistorySummary(fragment.Text), 700),
336						Terms:   historyTerms(fragment.Text),
337					})
338				}
339			}
340		}
341		return records, scanner.Err()
342	}
