344	func extractHistoryFragments(line string, allowRawText bool) []historyFragment {
345		var obj map[string]any
346		if err := json.Unmarshal([]byte(line), &obj); err != nil {
347			if !allowRawText {
348				return nil
349			}
350			return []historyFragment{{Text: line, Source: "text"}}
351		}
352		return extractHistoryJSONFragments(obj)
353	}
354	
355	func extractHistoryJSONFragments(obj map[string]any) []historyFragment {
356		recordType := jsonString(obj["type"])
357		payload := jsonMap(obj["payload"])
358		switch recordType {
359		case "session_meta", "turn_context", "permission-mode":
360			return nil
361		case "agent_message":
362			return stringFragment(obj["message"], "assistant_message")
363		case "event_msg":
364			return extractCodexEventFragments(payload)
365		case "response_item":
366			return extractCodexResponseFragments(payload)
367		case "assistant":
368			return extractClaudeMessageFragments(obj, "assistant")
369		case "user":
370			return extractClaudeToolResultFragments(obj)
371		case "progress":
372			return nil
373		default:
374			if message := jsonString(obj["message"]); message != "" {
375				return []historyFragment{{Text: message, Source: "message"}}
376			}
377			return nil
378		}
379	}
380	
381	func extractCodexEventFragments(payload map[string]any) []historyFragment {
382		switch jsonString(payload["type"]) {
383		case "agent_message":
384			return stringFragment(payload["message"], "assistant_message")
385		case "user_message":
386			return nil
387		case "task_complete":
388			return stringFragment(payload["last_agent_message"], "final_answer")
389		case "exec_command_end":
390			command := compactJSONValue(payload["command"])
391			return []historyFragment{{Text: command, Source: "tool_call:exec_command"}}
392		case "patch_apply_end":
393			parts := []string{"apply_patch", jsonString(payload["stdout"]), jsonString(payload["stderr"]), compactJSONValue(payload["changes"])}
394			return []historyFragment{{Text: strings.Join(parts, " "), Source: "tool_call:apply_patch"}}
395		default:
396			return nil
397		}
398	}
399	
400	func extractCodexResponseFragments(payload map[string]any) []historyFragment {
401		switch jsonString(payload["type"]) {
402		case "message":
403			role := jsonString(payload["role"])
404			if role != "assistant" {
405				return nil
406			}
407			return extractContentFragments(payload["content"], role+"_message")
408		case "function_call":
409			name := jsonString(payload["name"])
410			return []historyFragment{{Text: strings.TrimSpace(name + " " + compactJSONValue(payload["arguments"])), Source: historyToolCallSource(name)}}
411		case "custom_tool_call":
412			name := jsonString(payload["name"])
413			return []historyFragment{{Text: strings.TrimSpace(name + " " + compactJSONValue(payload["input"])), Source: historyToolCallSource(name)}}
414		case "function_call_output":
415			return extractToolResultFacts(jsonString(payload["output"]))
416		default:
417			return nil
418		}
419	}
420	
421	func extractClaudeToolResultFragments(obj map[string]any) []historyFragment {
422		message := jsonMap(obj["message"])
423		if len(message) == 0 {
424			return nil
425		}
426		content, ok := message["content"].([]any)
427		if !ok {
428			return nil
429		}
430		var fragments []historyFragment
431		for _, item := range content {
432			block := jsonMap(item)
433			if jsonString(block["type"]) != "tool_result" {
434				continue
435			}
436			fragments = append(fragments, extractToolResultFacts(firstNonEmptyString(block["content"], block["text"]))...)
437		}
438		return fragments
439	}
440	
441	func extractClaudeMessageFragments(obj map[string]any, role string) []historyFragment {
442		message := jsonMap(obj["message"])
443		if len(message) == 0 {
444			return nil
445		}
446		return extractContentFragments(message["content"], role+"_message")
447	}
448	
449	func extractContentFragments(content any, source string) []historyFragment {
450		switch value := content.(type) {
451		case string:
452			return []historyFragment{{Text: value, Source: source}}
453		case []any:
454			var fragments []historyFragment
455			for _, item := range value {
456				block := jsonMap(item)
457				if len(block) == 0 {
458					if text := fmt.Sprint(item); strings.TrimSpace(text) != "" {
459						fragments = append(fragments, historyFragment{Text: text, Source: source})
460					}
461					continue
462				}
463				blockType := jsonString(block["type"])
464				switch blockType {
465				case "tool_use":
466					name := jsonString(block["name"])
467					text := strings.TrimSpace(name + " " + compactJSONValue(block["input"]))
468					fragments = append(fragments, historyFragment{Text: text, Source: historyToolCallSource(name)})
469					fragments = append(fragments, extractToolResultFacts(text)...)
470				case "tool_result":
471					fragments = append(fragments, extractToolResultFacts(firstNonEmptyString(block["content"], block["text"]))...)
472				default:
473					if text := firstNonEmptyString(block["text"], block["input_text"], block["output_text"], block["content"]); text != "" {
474						fragments = append(fragments, historyFragment{Text: text, Source: source})
475					}
476				}
477			}
478			return fragments
479		default:
480			return nil
481		}
482	}
483	
484	func extractToolResultFacts(text string) []historyFragment {
485		text = strings.TrimSpace(text)
486		if text == "" || !historyTextHasCodeFactSignal(text) {
487			return nil
488		}
489		lines := strings.Split(text, "\n")
490		seen := map[string]struct{}{}
491		var fragments []historyFragment
492		lastEnd := -1
493		for i, line := range lines {
494			if i < lastEnd {
495				continue
496			}
497			if !historyLineHasCodeFactSignal(line) {
498				continue
499			}
500			start := max(0, i-2)
501			end := min(len(lines), i+4)
502			snippet := cleanHistoryCodeFactSnippet(cleanHistorySummary(strings.Join(lines[start:end], " ")))
503			if snippet == "" {
504				continue
505			}
506			if _, ok := seen[snippet]; ok {
507				continue
508			}
509			seen[snippet] = struct{}{}
510			fragments = append(fragments, historyFragment{Text: snippet, Source: "tool_result_fact"})
511			lastEnd = end
512			if len(fragments) >= 8 {
513				break
514			}
515		}
516		return fragments
517	}
518	
519	func cleanHistoryCodeFactSnippet(value string) string {
520		value = strings.TrimSpace(strings.TrimPrefix(value, "content:"))
521		if value == "" {
522			return ""
523		}
524		return truncateString(value, 4000)
525	}
526	
527	func historyTextHasCodeFactSignal(text string) bool {
528		lower := strings.ToLower(text)
529		return containsAny(lower,
530			"attributionbasecommit", "realignattributionbase", "human_added", "human added",
531			"resolve transcript path", "resolvetranscriptpath", "transcriptpath", "state.transcriptpath",
532			"reresolvestonestedlayout", "re-resolved path", "subsequent reads use",
533			"brainignore", ".brainignore", ".github", "github workflow", "workflow/tooling",
534			"seed-agent", "seed agent", "schema contract", "bare auth",
535		)
536	}
537	
538	func historyLineHasCodeFactSignal(line string) bool {
539		return historyTextHasCodeFactSignal(line)
540	}
541	
542	func classifyHistoryFragment(fragment historyFragment) []string {
543		lower := strings.ToLower(fragment.Text)
544		narrative := isHistoryNarrativeSource(fragment.Source)
545		tool := strings.HasPrefix(fragment.Source, "tool_call")
546		validationTool := tool && !strings.Contains(fragment.Source, "apply_patch")
547		kinds := map[string]struct{}{}
548		if fragment.Source == "tool_result_fact" {
549			kinds["code_fact"] = struct{}{}
550		}
551		if narrative && isDecisionFragment(fragment.Source, lower) {
552			kinds["decision"] = struct{}{}
553		}
554		if narrative && containsAny(lower, "learned", "root cause", "turns out", "lesson", "failure mode", "the issue", "the bug", "found that") {
555			kinds["learning"] = struct{}{}
556		}
557		if (narrative || validationTool) && containsAny(lower, "go test", "pytest", "npm test", "mise run", "validation", "regression test", "hidden validation", "tests pass", "validated with", "ran tests") {
558			kinds["validation"] = struct{}{}
559		}
560		if narrative && isArchitectureFragment(lower) {
561			kinds["architecture"] = struct{}{}
562		}
563		if tool || (fragment.Source == "text" && containsAny(lower, "tool_use", "function_call", "apply_patch", "exec_command", "\"cmd\"", "entire brain", "git grep", "bash ", "read ", "write ")) {
564			kinds["tool_call"] = struct{}{}
565		}
566		out := make([]string, 0, len(kinds))
567		for kind := range kinds {
568			out = append(out, kind)
569		}
570		sort.Strings(out)
571		return out
572	}
573	
574	func isHistoryNarrativeSource(source string) bool {
575		switch source {
576		case "assistant_message", "final_answer", "message", "text":
577			return true
578		default:
579			return false
580		}
581	}
582	
583	func historyToolCallSource(name string) string {
584		name = strings.ToLower(strings.TrimSpace(name))
585		if name == "" {
586			return "tool_call"
587		}
588		return "tool_call:" + name
589	}
590	
591	func historyLineMayContainIndexedContent(text string) bool {
592		lower := strings.ToLower(text)
593		if containsAny(lower, `"type":"session_meta"`, `"type": "session_meta"`, `"type":"turn_context"`, `"type": "turn_context"`, `"type":"permission-mode"`, `"type": "permission-mode"`) {
594			return false
595		}
596		return containsAny(lower,
597			"decision", "decided", "we chose", "we choose", "instead of", "rationale",
