747	func normalizeHistorySearchText(value string) string {
748		var b strings.Builder
749		runes := []rune(value)
750		lastSpace := true
751		for i, r := range runes {
752			if unicode.IsLetter(r) || unicode.IsDigit(r) {
753				if !lastSpace && historyCamelBoundary(runes, i) {
754					b.WriteByte(' ')
755				}
756				b.WriteRune(unicode.ToLower(r))
757				lastSpace = false
758				continue
759			}
760			if !lastSpace {
761				b.WriteByte(' ')
762				lastSpace = true
763			}
764		}
765		return strings.TrimSpace(b.String())
766	}
767	
768	func historyCamelBoundary(runes []rune, index int) bool {
769		if index <= 0 || index >= len(runes) {
770			return false
771		}
772		current := runes[index]
773		previous := runes[index-1]
774		if !unicode.IsLetter(current) || !(unicode.IsLetter(previous) || unicode.IsDigit(previous)) || !unicode.IsUpper(current) {
775			return false
776		}
777		if unicode.IsLower(previous) || unicode.IsDigit(previous) {
778			return true
779		}
780		if unicode.IsUpper(previous) && index+1 < len(runes) && unicode.IsLower(runes[index+1]) {
781			return true
782		}
783		return false
784	}
