791		text = strings.ToLower(text)
792		if strings.Contains(text, query) {
793			return true
794		}
795		normalizedText := normalizeHistorySearchText(text)
796		normalizedQuery := normalizeHistorySearchText(query)
797		if normalizedQuery == "" {
798			return false
799		}
800		if strings.Contains(normalizedText, normalizedQuery) {
801			return true
802		}
803		return false
804	}
