810	func rankHistoryRecords(index historyIndex, kind, query string, limit int) []historyRecord {
811		if limit <= 0 {
812			return nil
813		}
814		allowed := historyInspectKinds(kind)
815		scored := make([]scoredHistoryRecord, 0, min(len(index.Records), limit))
816		seen := map[string]struct{}{}
817		for i, record := range index.Records {
818			if len(allowed) > 0 {
819				if _, ok := allowed[record.Kind]; !ok {
820					continue
821				}
822			}
823			score := historyRecordQueryScore(record, query)
824			if score == 0 {
825				continue
826			}
827			score += historyInspectKindPreference(kind, record.Kind)
828			matchKey := normalizeHistorySearchText(record.Summary)
829			if _, ok := seen[matchKey]; ok {
830				continue
831			}
832			seen[matchKey] = struct{}{}
833			scored = append(scored, scoredHistoryRecord{Record: record, Score: score, Order: i})
834		}
835		sort.Slice(scored, func(i, j int) bool {
836			left, right := scored[i], scored[j]
837			if left.Score != right.Score {
838				return left.Score > right.Score
839			}
840			if historyKindRank(left.Record.Kind) != historyKindRank(right.Record.Kind) {
841				return historyKindRank(left.Record.Kind) > historyKindRank(right.Record.Kind)
842			}
843			if left.Record.Path != right.Record.Path {
844				return left.Record.Path > right.Record.Path
845			}
846			if left.Record.Line != right.Record.Line {
847				return left.Record.Line < right.Record.Line
848			}
849			return left.Order < right.Order
850		})
851		if len(scored) > limit {
852			scored = scored[:limit]
853		}
854		records := make([]historyRecord, 0, len(scored))
855		for _, item := range scored {
856			records = append(records, item.Record)
857		}
858		return records
859	}
