func dedupeBrainBriefActions(actions []brainBriefAction, limit int) []brainBriefAction {
    if limit <= 0 {
        return nil
    }
    seen := map[string]struct{}{}
    out := make([]brainBriefAction, 0, min(len(actions), limit))
    for _, action := range actions {
        // **NEW: More granular dedup key (action description, not full evidence)**
        key := strings.ToLower(action.File + "\x00" + action.Symbol + "\x00" + action.Action)
        if _, ok := seen[key]; ok {
            continue
        }
        seen[key] = struct{}{}
        out = append(out, action)
        if len(out) >= limit {
