export const meta = {
  name: 'brain-progress-audit',
  description: 'Derive current per-model brain status + remaining gaps from the actual result data and delivery code',
  phases: [
    { title: 'Assess', detail: 'parallel: per-model status, open follow-ups, coverage gaps' },
    { title: 'Synthesize', detail: 'progress report + prioritized what-is-left' },
  ],
}

const ROOT = '/Users/suhaan/Documents/Coding/entire-brain'
const BENCH = `${ROOT}/benchmarks/agent-brain`

const ground = `Repo: ${ROOT}. Benchmark harness: ${BENCH}. The campaign proves whether a local repo "brain" (semantic index + real Entire session history) beats grep for coding agents, across Claude {haiku,sonnet,opus} and Codex {gpt-5.5, gpt-5.4-mini} at efforts {low,medium,high,xhigh}, via two delivery paths: CLI (full_cli_compact) and MCP (mcp_history), vs a no_brain baseline. Two cli tasks: entireio-cli-transcript-reresolve (easy/greppable) and entireio-cli-review-base-flag-scope (hard/invariant). GROUND EVERYTHING IN ACTUAL FILES — read the result docs and result suites and cite real numbers; do NOT speculate or rely on prior knowledge. Read-only.`

const statusAgent = agent(`${ground}
Produce a PER-MODEL × PER-DELIVERY status matrix. For EACH of {haiku, sonnet, opus, gpt-5.5, gpt-5.4-mini} and each delivery {CLI=full_cli_compact, MCP=mcp_history}, classify as one of: WIN (quality+efficiency), EFFICIENCY-ONLY (no quality headroom or quality flat), OPEN (brain hurts or volatile), or UNTESTED — with the supporting numbers.
Sources to read: ${BENCH}/results/CLI_PROOF_SUMMARY.md, ${BENCH}/results/RESULTS.md, ${BENCH}/results/OPUS_OPTIMIZATION.md, ${BENCH}/results/GPT_MCP_FIX.md. Also confirm the CURRENT delivery each model gets by reading prompt_for + wants_disciplined_mcp + OPUS_COMPACT_MODELS + COMPACT_STRICT_MODELS in ${BENCH}/run.py. Note where the latest fix (disciplined MCP) changed a status vs the original v3 numbers. Be concise: a table + one line of evidence per cell.`, { phase: 'Assess', label: 'per-model status' })

const followupAgent = agent(`${ground}
Find EVERY explicitly deferred / not-adopted / experimental / overfit / TODO item in the code and docs — the concrete backlog. Read ${BENCH}/run.py (comments around OPUS_COMPACT_MODELS, COMPACT_STRICT_MODELS, wants_disciplined_mcp, prompt_for), ${ROOT}/internal/cli/agent_surface.go (the action_checklist generator — is it hardcoded to Ultron-specific patterns? the brainBriefTaskTermBonus ranking — is it labelled experimental?), and the result docs (${BENCH}/results/GPT_MCP_FIX.md "follow-ups", ${BENCH}/results/OPUS_OPTIMIZATION.md, ${BENCH}/results/CLI_PROOF_SUMMARY.md "open problem" notes). For each item give: what it is, why it's deferred, file:line, and the risk if left. Especially: (a) the "brief's own history section misses the invariant" general fix, (b) action_checklist being Ultron-pattern-only (empty for cli tasks), (c) gpt-5.5 CLI-only Opus-style not adopted (n=3), (d) the experimental task-term ranking feature, (e) gpt-5 (full) untested. Concise bullet list.`, { phase: 'Assess', label: 'open follow-ups' })

const coverageAgent = agent(`${ground}
Identify COVERAGE GAPS — what has NOT been tested. Read the task files in ${BENCH}/tasks/ and the result suite directory names in ${BENCH}/results/ (ls). Report: (1) which (model × effort × delivery) cells lack matched data; (2) the benchmark only uses 2 cli tasks + an easy/hard split — what classes of task/regression are unrepresented (e.g. multi-file fixes, new-feature, non-Go repos); (3) statistical power (the n per cell — is it n=3, n=5?); (4) any model in the matrix never run on MCP-fixed delivery; (5) the gpt-5.4-mini "high/xhigh quality gap" claim from v3 vs the finding it didn't reproduce on these tasks — what would actually test it (cells where no_brain is NOT saturated). Concise bullet list grounded in the actual files.`, { phase: 'Assess', label: 'coverage gaps' })

const [status, followups, coverage] = await Promise.all([statusAgent, followupAgent, coverageAgent])

const synthesis = await agent(`You are writing a concise progress + remaining-work report for the entire-brain benchmark campaign. Synthesize the three grounded assessments below into: (1) "DONE" — what's solved, with the model and the number; (2) "OPEN / LEFT TO FIX" — prioritized (P0/P1/P2) with the specific fix and why it matters; (3) a one-line bottom line. Be ruthless about honesty: distinguish quality wins from efficiency-only, and flag where a claimed gap didn't reproduce. Keep it tight — a CEO-readable status, not a wall of text. Do not invent numbers; use only what's in the assessments.

=== PER-MODEL STATUS ===
${status}

=== OPEN FOLLOW-UPS (code/docs backlog) ===
${followups}

=== COVERAGE GAPS ===
${coverage}`, { phase: 'Synthesize', label: 'progress + what-is-left' })

return synthesis

