func TestBrainBriefIndexedHistorySurfacesInvariantIdentifier(t *testing.T) {
	// The brief's history must carry the exact invariant. A whole-task ("compound") query
	// dilutes a single identifier among prose terms (noise records that echo the prose rank
	// high); the focused per-identifier pass must still surface the record that NAMES the
	// invariant — the regression that previously left brain_brief pointing at the right file
	// with no "what to change".
	index := historyIndex{Records: []historyRecord{
		{Kind: "tool_call", Path: "sessions/main/noise1.jsonl", Line: 1,
			Summary: "Reviewing the scope of the base branch regression in the review command flow."},
		{Kind: "tool_call", Path: "sessions/main/noise2.jsonl", Line: 2,
			Summary: "The review scope base ref handling needs a regression test for the base flag."},
		{Kind: "decision", Path: "sessions/main/invariant.jsonl", Line: 3,
			Summary: `Fix: the review diff range must use scopeBaseRef+"..HEAD", not a hardcoded "master..HEAD" base.`},
	}}
	task := "review base flag scope regression: the explicit base ref must thread through | reviewContextCommitMessages scopeBaseRef BaseFlagThreadsThroughToPromptAndBanner"

	matches := brainBriefIndexedHistoryMatches(index, task, 3)
	if len(matches) == 0 {
		t.Fatal("expected focused per-identifier history matches")
	}
	if !strings.Contains(matches[0].Excerpt, "scopeBaseRef") {
		t.Fatalf("focused history did not surface the scopeBaseRef invariant first: %+v", matches)
	}

	// Prose-only task with no extractable identifiers falls back to the whole-task query.
	fallback := brainBriefIndexedHistoryMatches(index, "fix the review base branch handling", 3)
	if len(fallback) == 0 {
		t.Fatal("expected fallback whole-task history matches for a prose-only task")
	}
}

